begin;
create table public.arena_alliance_pro_checkout_intents(id uuid primary key default gen_random_uuid(),alliance_id uuid not null references public.arena_alliances(id)on delete cascade,created_by uuid not null references public.profiles(id)on delete cascade,status text not null default'pending'check(status in('pending','completed','expired')),created_at timestamptz not null default now());alter table public.arena_alliance_pro_checkout_intents enable row level security;alter table public.arena_alliance_pro_checkout_intents force row level security;revoke all on public.arena_alliance_pro_checkout_intents from anon,authenticated;
create or replace function public.arena_get_alliance_pro()returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;return(select jsonb_build_object('is_pro',public.arena_alliance_has_pro(v_alliance),'can_subscribe',v_role='founder','status',coalesce(s.status,'inactive'),'period_end',s.current_period_end,'benefits',jsonb_build_array('20 cenários premium','Brasões PRO','Passe coletivo premium','Mais metas e histórico','Identidade visual exclusiva'))from public.arena_alliances a left join public.arena_alliance_subscriptions s on s.alliance_id=a.id where a.id=v_alliance);end;$$;
create or replace function public.arena_prepare_alliance_pro_checkout()returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;v_id uuid;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null or v_role<>'founder'then raise exception'founder required';end if;if public.arena_alliance_has_pro(v_alliance)then raise exception'already pro';end if;insert into public.arena_alliance_pro_checkout_intents(alliance_id,created_by)values(v_alliance,v_user)returning id into v_id;return jsonb_build_object('intent_id',v_id,'alliance_id',v_alliance);end;$$;
create or replace function public.arena_fulfill_alliance_pro(p_intent_id uuid,p_subscription_id text,p_customer_id text,p_status text,p_period_end timestamptz)returns void language plpgsql security definer set search_path='' as $$declare v_intent public.arena_alliance_pro_checkout_intents%rowtype;begin select*into v_intent from public.arena_alliance_pro_checkout_intents where id=p_intent_id for update;if not found then raise exception'intent unavailable';end if;insert into public.arena_alliance_subscriptions(alliance_id,provider,provider_subscription_id,status,current_period_end)values(v_intent.alliance_id,'stripe',p_subscription_id,p_status,p_period_end)on conflict(alliance_id)do update set provider_subscription_id=excluded.provider_subscription_id,status=excluded.status,current_period_end=excluded.current_period_end;update public.arena_alliance_pro_checkout_intents set status='completed'where id=p_intent_id;end;$$;
revoke all on function public.arena_get_alliance_pro(),public.arena_prepare_alliance_pro_checkout()from public;grant execute on function public.arena_get_alliance_pro(),public.arena_prepare_alliance_pro_checkout()to authenticated;revoke all on function public.arena_fulfill_alliance_pro(uuid,text,text,text,timestamptz)from public;grant execute on function public.arena_fulfill_alliance_pro(uuid,text,text,text,timestamptz)to service_role;commit;
